INSERT INTO library_sections (key, category, subcategory, name, description, keywords, tree, sort_order, is_hidden)
VALUES (
  'tallaby-faq',
  'faq',
  'accordion',
  '{"ar":"كلاسيك: الأسئلة بالمجموعات","en":"Classic: grouped questions"}'::jsonb,
  '{"ar":"أسئلة مقسمة مجموعات، وكارت مساعدة فيه واتساب والتواصل.","en":"Questions in groups, then a help card with WhatsApp and contact."}'::jsonb,
  ARRAY['faq', 'questions', 'classic', 'tallaby', 'أسئلة', 'كلاسيك']::text[],
  '{"breakpointStyles":{"mobile":{"paddingBottom":40,"paddingTop":40}},"children":[{"children":[{"breakpointStyles":{"mobile":{"gap":28}},"children":[{"children":[{"children":[],"props":{"field":"heading","level":"h2","text":"الطلبات","translations":{"en":{"text":"Orders"}}},"style":{"fontSize":"xl","fontWeight":"bold"},"type":"heading"},{"children":[{"children":[{"children":[],"props":{"field":"text","text":"هتشوف صفحة تأكيد وتوصلك رسالة. وبنكلمك نأكد الطلبات الكاش.","translations":{"en":{"text":"You see a confirmation page and get a message. We also call to confirm cash orders."}}},"type":"paragraph"}],"props":{"field":"faq","title":"أعرف إزاي إن طلبي وصل؟","translations":{"en":{"title":"How do I know my order went through?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-2","text":"أيوه، لحد ما يتشحن. ألغيه من صفحة الطلب أو كلمنا.","translations":{"en":{"text":"Yes, until it ships. Cancel from your order page or message us."}}},"type":"paragraph"}],"props":{"field":"faq-2","title":"أقدر أعدّل أو ألغي طلبي؟","translations":{"en":{"title":"Can I change or cancel my order?"}}},"type":"accordionItem"}],"props":{"field":"items","label":"الأسئلة","role":"items","translations":{"en":{"label":"Questions"}}},"style":{"gap":0},"type":"accordion"}],"props":{"field":"box-3","label":"مجموعة","translations":{"en":{"label":"Group"}}},"style":{"gap":4},"type":"vFlex"},{"children":[{"children":[],"props":{"field":"heading-2","level":"h2","text":"التوصيل","translations":{"en":{"text":"Delivery"}}},"style":{"fontSize":"xl","fontWeight":"bold"},"type":"heading"},{"children":[{"children":[{"children":[],"props":{"field":"text-3","text":"القاهرة والجيزة من يوم ليومين، وباقي المحافظات من ٢ لـ ٦ أيام.","translations":{"en":{"text":"Cairo and Giza in 1 to 2 days, other governorates in 2 to 6 days."}}},"type":"paragraph"}],"props":{"field":"faq-3","title":"التوصيل بياخد قد إيه؟","translations":{"en":{"title":"How long does delivery take?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-4","text":"من صفحة طلباتي بعد تسجيل الدخول، أو من الرابط في رسالة التأكيد.","translations":{"en":{"text":"From My orders after you sign in, or from the link in your confirmation message."}}},"type":"paragraph"}],"props":{"field":"faq-4","title":"أتابع طلبي إزاي؟","translations":{"en":{"title":"How do I track my order?"}}},"type":"accordionItem"}],"props":{"field":"items-2","label":"الأسئلة","role":"items","translations":{"en":{"label":"Questions"}}},"style":{"gap":0},"type":"accordion"}],"props":{"field":"box-4","label":"مجموعة","translations":{"en":{"label":"Group"}}},"style":{"gap":4},"type":"vFlex"},{"children":[{"children":[],"props":{"field":"heading-3","level":"h2","text":"الاسترجاع والدفع","translations":{"en":{"text":"Returns and payment"}}},"style":{"fontSize":"xl","fontWeight":"bold"},"type":"heading"},{"children":[{"children":[{"children":[],"props":{"field":"text-5","text":"تقدر ترجع أي منتج مش مستخدم خلال ١٤ يوم في علبته الأصلية.","translations":{"en":{"text":"Return any unused item within 14 days in its original box."}}},"type":"paragraph"}],"props":{"field":"faq-5","title":"سياسة الاسترجاع إيه؟","translations":{"en":{"title":"What is your return policy?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-6","text":"الدفع عند الاستلام والكارت والمحافظ الإلكترونية، حسب اللي يظهر في صفحة الدفع.","translations":{"en":{"text":"Cash on delivery, card and mobile wallets, as shown at checkout."}}},"type":"paragraph"}],"props":{"field":"faq-6","title":"بتقبلوا إيه في الدفع؟","translations":{"en":{"title":"Which payment methods do you accept?"}}},"type":"accordionItem"}],"props":{"field":"items-3","label":"الأسئلة","role":"items","translations":{"en":{"label":"Questions"}}},"style":{"gap":0},"type":"accordion"}],"props":{"field":"box-5","label":"مجموعة","translations":{"en":{"label":"Group"}}},"style":{"gap":4},"type":"vFlex"},{"children":[{"children":[{"children":[],"props":{"field":"heading-4","level":"h3","text":"لسه عندك سؤال؟","translations":{"en":{"text":"Still have a question?"}}},"style":{"fontSize":"lg","fontWeight":"bold"},"type":"heading"},{"children":[],"props":{"field":"text-7","text":"ابعتلنا وهيرد عليك شخص حقيقي.","translations":{"en":{"text":"Message us and a real person will reply."}}},"style":{"color":"muted"},"type":"paragraph"}],"props":{"field":"box-7","label":"النص","translations":{"en":{"label":"Copy"}}},"style":{"gap":4},"type":"vFlex"},{"children":[{"children":[],"props":{"field":"cta","href":"https://wa.me/201000000000","label":"واتساب","role":"cta","translations":{"en":{"label":"WhatsApp"}},"variant":"solid"},"style":{"fontWeight":"bold","paddingEnd":24,"paddingStart":24,"radius":999},"type":"button"},{"children":[],"props":{"field":"secondary-cta","href":"/contact","label":"تواصل معنا","role":"secondaryCta","translations":{"en":{"label":"Contact us"}},"variant":"outline"},"style":{"background":"background","borderColor":"border","borderWidth":1,"color":"foreground","fontWeight":"bold","hover":{"background":"secondary"},"paddingEnd":24,"paddingStart":24,"radius":999},"type":"button"}],"props":{"field":"box-8","label":"الأزرار","translations":{"en":{"label":"Buttons"}}},"style":{"gap":8},"type":"hFlex"}],"props":{"field":"box-6","label":"كارت المساعدة","translations":{"en":{"label":"Help card"}}},"style":{"alignItems":"center","background":"secondary","gap":16,"justifyContent":"between","paddingBottom":24,"paddingEnd":24,"paddingStart":24,"paddingTop":24,"radius":16},"type":"hFlex"}],"props":{"field":"box-2","label":"المحتوى","translations":{"en":{"label":"Content"}}},"style":{"gap":36,"maxWidth":"820px"},"type":"vFlex"}],"props":{"field":"box","label":"الحاوية","translations":{"en":{"label":"Container"}}},"type":"container"}],"props":{"field":"section","label":"الأسئلة","translations":{"en":{"label":"Questions"}}},"style":{"paddingBottom":0,"paddingTop":28},"type":"section"}'::jsonb,
