INSERT INTO library_sections (key, category, subcategory, name, description, keywords, tree, sort_order, is_hidden)
VALUES (
  'atelier-faq',
  'faq',
  'accordion',
  '{"ar":"أتيليه: أسئلة وأجوبة","en":"Atelier: questions"}'::jsonb,
  '{"ar":"قائمة أسئلة قابلة للفتح، وتحتها رابط للتواصل.","en":"An accordion of questions with a contact link under it."}'::jsonb,
  ARRAY['faq', 'atelier', 'questions', 'أسئلة']::text[],
  '{"breakpointStyles":{"mobile":{"paddingBottom":56,"paddingTop":56}},"children":[{"children":[{"children":[{"children":[{"children":[{"children":[],"props":{"field":"text","text":"في صفحة كل قطعة جدول مقاسات بالسنتيمتر. لو بين مقاسين، اختر الأكبر أو راسلنا وسنساعدك.","translations":{"en":{"text":"Each piece has a size chart in centimetres on its page. Between two sizes, take the larger or message us and we will help."}}},"type":"paragraph"}],"props":{"field":"faq","open":true,"title":"كيف أختار مقاسي؟","translations":{"en":{"title":"How do I pick my size?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-2","text":"من يومين إلى خمسة أيام عمل حسب المحافظة. تصلك رسالة برقم التتبع عند الشحن.","translations":{"en":{"text":"Two to five working days depending on your governorate. You get a tracking message when it ships."}}},"type":"paragraph"}],"props":{"field":"faq-2","title":"كم يستغرق التوصيل؟","translations":{"en":{"title":"How long does delivery take?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-3","text":"نعم، خلال ١٤ يومًا من الاستلام إذا كانت القطعة بحالتها وبالبطاقة. التفاصيل في صفحة الاسترجاع.","translations":{"en":{"text":"Yes, within 14 days of delivery if the piece is unworn with its tag. Details are on the returns page."}}},"type":"paragraph"}],"props":{"field":"faq-3","title":"هل يمكنني الاستبدال أو الاسترجاع؟","translations":{"en":{"title":"Can I exchange or return a piece?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-4","text":"الدفع عند الاستلام أو بالبطاقة أو المحفظة، حسب ما يظهر لك في صفحة الدفع.","translations":{"en":{"text":"Cash on delivery, card or wallet, as shown at checkout."}}},"type":"paragraph"}],"props":{"field":"faq-4","title":"ما طرق الدفع المتاحة؟","translations":{"en":{"title":"How can I pay?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-5","text":"اغسل الكتان على ٣٠ درجة وجففه في الظل. الصوف تنظيف جاف أو غسيل يدوي بماء بارد.","translations":{"en":{"text":"Wash linen at 30°C and dry it in the shade. Wool: dry clean, or hand wash in cold water."}}},"type":"paragraph"}],"props":{"field":"faq-5","title":"كيف أعتني بالكتان والصوف؟","translations":{"en":{"title":"How do I care for linen and wool?"}}},"type":"accordionItem"},{"children":[{"children":[],"props":{"field":"text-6","text":"من صفحة طلباتي بعد تسجيل الدخول، أو من الرابط في رسالة تأكيد الطلب.","translations":{"en":{"text":"From My orders after you sign in, or from the link in your order confirmation."}}},"type":"paragraph"}],"props":{"field":"faq-6","title":"أين أتابع طلبي؟","translations":{"en":{"title":"Where do I follow my order?"}}},"type":"accordionItem"}],"props":{"field":"items","label":"الأسئلة","role":"items","translations":{"en":{"label":"Questions"}}},"style":{"gap":0},"type":"accordion"},{"breakpointStyles":{"mobile":{"alignItems":"start","direction":"column","gap":12}},"children":[{"children":[],"props":{"field":"text-7","text":"لم تجد إجابتك؟","translations":{"en":{"text":"Didn''t find your answer?"}}},"style":{"fontFamily":"heading","fontSize":"xl","fontWeight":"medium","letterSpacing":"normal","lineHeight":"tight"},"type":"text"},{"children":[{"children":[{"children":[],"props":{"field":"text-8","text":"تواصل معنا","translations":{"en":{"text":"Contact us"}}},"style":{"fontSize":"xs","fontWeight":"medium","letterSpacing":"wider","textTransform":"uppercase"},"type":"text"},{"children":[],"props":{"field":"icon","name":"arrow"},"style":{"fontSize":"sm"},"type":"icon"}],"props":{"field":"box-4","label":"نص الرابط","translations":{"en":{"label":"Link text"}}},"style":{"alignItems":"center","gap":8,"wrap":false},"type":"hFlex"}],"props":{"field":"link","href":"/contact","label":"رابط","role":"link","translations":{"en":{"label":"Link"}}},"style":{"borderColor":"foreground","color":"foreground","hover":{"opacity":70},"paddingBottom":4,"paddingEnd":0,"paddingStart":0,"paddingTop":0},"type":"linkBlock"}],"props":{"field":"box-3","label":"التواصل","translations":{"en":{"label":"Contact"}}},"style":{"alignItems":"center","gap":20,"justifyContent":"between","marginTop":40},"type":"hFlex"}],"props":{"field":"box-2","label":"المحتوى","translations":{"en":{"label":"Content"}}},"style":{"marginStart":0,"maxWidth":"760px"},"type":"div"}],"props":{"field":"box","label":"الحاوية","translations":{"en":{"label":"Container"}}},"type":"container"}],"props":{"field":"section","label":"الأسئلة","translations":{"en":{"label":"Questions"}}},"style":{"paddingBottom":96,"paddingTop":96},"type":"section"}'::jsonb,
  10410,
